<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$term=filter_var($_POST['term_id']??null,FILTER_VALIDATE_INT);$class=filter_var($_POST['class_id']??null,FILTER_VALIDATE_INT);$teacher=trim((string)($_POST['teacher_comment']??''));$head=trim((string)($_POST['head_comment']??''));$canManage=in_array($user['role'],['Administrator','Head'],true);$back='../?page=reports&term_id='.(int)$term.'&class_id='.(int)$class.'&student_id='.(int)$student;
if(!$student||!$term||!$class||strlen($teacher)>500||strlen($head)>500){$_SESSION['error']='Check the report comment and try again.';header('Location: '.$back);exit;}
$pdo=db();$stmt=$pdo->prepare('SELECT c.form_level,c.stream,c.academic_year,c.class_teacher_id,t.academic_year AS term_year FROM class_groups c JOIN school_terms t ON t.id=:term WHERE c.id=:class');$stmt->execute(['term'=>$term,'class'=>$class]);$context=$stmt->fetch();if(!$context||(int)$context['academic_year']!==(int)$context['term_year']){$_SESSION['error']='The selected class and term do not match.';header('Location: ../?page=reports');exit;}if(!$canManage&&(int)$context['class_teacher_id']!==(int)$user['id']){http_response_code(403);exit('Only the assigned class teacher can write teacher comments.');}
$valid=$pdo->prepare("SELECT s.id FROM students s JOIN student_enrolments e ON e.student_id=s.id WHERE s.id=:student AND e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=(SELECT ends_on FROM school_terms WHERE id=:term_end) AND (e.end_date IS NULL OR e.end_date>=(SELECT starts_on FROM school_terms WHERE id=:term_start)) LIMIT 1");$valid->execute(['student'=>$student,'year'=>$context['term_year'],'form'=>$context['form_level'],'stream'=>$context['stream'],'term_end'=>$term,'term_start'=>$term]);if(!$valid->fetch()){http_response_code(403);exit('Learner is outside the selected class for this term.');}
try{$pdo->beginTransaction();$existing=$pdo->prepare('SELECT teacher_comment,head_comment FROM term_report_comments WHERE student_id=:student AND term_id=:term FOR UPDATE');$existing->execute(['student'=>$student,'term'=>$term]);$old=$existing->fetch();$savedTeacher=$teacher;$savedHead=$canManage?$head:($old['head_comment']??null);$up=$pdo->prepare('INSERT INTO term_report_comments (student_id,term_id,teacher_comment,head_comment,updated_by) VALUES (:student,:term,:teacher,:head,:user) ON DUPLICATE KEY UPDATE teacher_comment=VALUES(teacher_comment),head_comment=VALUES(head_comment),updated_by=VALUES(updated_by)');$up->execute(['student'=>$student,'term'=>$term,'teacher'=>$savedTeacher?:null,'head'=>$savedHead?:null,'user'=>$user['id']]);audit_log('reports.comments_saved','term_report_comments',null,['student_id'=>$student,'term_id'=>$term,'updated_head_comment'=>$canManage]);$pdo->commit();$_SESSION['notice']='Report comments saved.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Report comment save failed: '.$e->getMessage());$_SESSION['error']='Could not save report comments.';}
header('Location: '.$back);exit;
